// Add a highlight marker at Orion Nebula
HighlightMgr.addPoint("5h 35m 17.3s", "-5° 23′ 28″");

// Add a highlight marker at Sirius
HighlightMgr.addPoint("6h 45m 8.9s", "-16° 42′ 58″");

// Add a marker using decimal degrees
HighlightMgr.addPoint("83.822°", "-5.391°");

// Add multiple markers
HighlightMgr.addPoint("5h 35m 17.3s", "-5° 23′ 28″");
HighlightMgr.addPoint("5h 35m 20.0s", "-5° 25′ 00″");
HighlightMgr.addPoint("5h 35m 25.0s", "-5° 20′ 00″");

// Add a highlight at current date coordinates
HighlightMgr.addPointRaDec("2h 10m 15s", "60d 01m 15s");

// Add a highlight at the Sun's current position
var sunInfo = core.getObjectInfo("Sun");
if(sunInfo) {
    HighlightMgr.addPointRaDec(sunInfo["ra"], sunInfo["dec"]);
}

// Add a highlight at the Moon's current position
var moonInfo = core.getObjectInfo("Moon");
if(moonInfo) {
    HighlightMgr.addPointRaDec(moonInfo["ra"], moonInfo["dec"]);
}

// Add a highlight at zenith (directly overhead)
HighlightMgr.addPointAltAzi("90°", "0°");

// Add a highlight on the eastern horizon
HighlightMgr.addPointAltAzi("0°", "90°");

// Add a highlight on the southern meridian at 45° altitude
HighlightMgr.addPointAltAzi("45d", "180d");

// Add highlights at cardinal points
HighlightMgr.addPointAltAzi("0°", "0°");   // North horizon
HighlightMgr.addPointAltAzi("0°", "90°");  // East horizon
HighlightMgr.addPointAltAzi("0°", "180°"); // South horizon
HighlightMgr.addPointAltAzi("0°", "270°"); // West horizon

// Create a list of positions
var positions = [];
var pos1 = core.vec3d(0.5, 0.5, 0.707);
var pos2 = core.vec3d(0.2, 0.8, 0.566);
var pos3 = core.vec3d(0.9, 0.1, 0.424);
positions.push(pos1);
positions.push(pos2);
positions.push(pos3);

// Replace all highlights with the new list
HighlightMgr.fillHighlightList(positions);

// Clear all highlights by passing an empty list
HighlightMgr.fillHighlightList([]);

// Clear all highlight markers
HighlightMgr.cleanHighlightList();
core.debug("All highlight markers removed");

// Add markers then clear them
HighlightMgr.addPoint("2h 10m 15s", "60d 01m 15s");
HighlightMgr.addPoint("4h 20m 30s", "30d 15m 00s");
core.wait(3);
HighlightMgr.cleanHighlightList();
core.debug("Highlights cleared after 3 seconds");

// Set highlight color to bright red
var red = core.vec3f(1.0, 0.0, 0.0);
HighlightMgr.setColor(red);

// Set highlight color to cyan (default)
var cyan = core.vec3f(0.0, 1.0, 1.0);
HighlightMgr.setColor(cyan);

// Set highlight color to yellow
var yellow = core.vec3f(1.0, 1.0, 0.0);
HighlightMgr.setColor(yellow);

// Set highlight color to magenta
var magenta = core.vec3f(1.0, 0.0, 1.0);
HighlightMgr.setColor(magenta);

// Get current color
var currentColor = HighlightMgr.getColor();
core.debug("Current highlight color: RGB(" + currentColor[0] + ", " + currentColor[1] + ", " + currentColor[2] + ")");

// Get and display current color
var color = HighlightMgr.getColor();
core.debug("Highlight marker color: (" + color[0].toFixed(2) + ", " + color[1].toFixed(2) + ", " + color[2].toFixed(2) + ")");

// Use color in condition
if(color[0] > 0.8 && color[1] < 0.2 && color[2] < 0.2) {
    core.debug("Highlights are red");
}

// Small, subtle markers
HighlightMgr.setMarkersSize(8.0);

// Large, very visible markers
HighlightMgr.setMarkersSize(15.0);

// Default size
HighlightMgr.setMarkersSize(11.0);

// Extra large for presentations
HighlightMgr.setMarkersSize(20.0);

var size = HighlightMgr.getMarkersSize();
core.debug("Current marker size: " + size + " pixels");

var size = HighlightMgr.getMarkersSize();
core.debug("Current marker size: " + size + " px");

if(size < 10) {
    core.debug("Markers are small - consider increasing for better visibility");
}
